import {COSSENNE_TRAINERS} from './cossenne-data.js?v=0.90.48';
import {cossenneReady} from './cossenne-rules.js?v=0.87.0';
import {warehouseReady} from './cybressa-rules.js?v=0.90.20';
import {DATA} from './data.js?v=0.90.48';
import {legalForm,legalMoves} from './route-roster.js?v=0.87.0';
import {hospiceReady} from './hospice-quest.js?v=0.87.0';
import {LEADER_FORTS,FORT_STONE_BOARD,fortForRoom,fortForLeader} from './leader-fort-data.js?v=0.90.48';
export function leaderFortState(state,key){state.leaderForts??={};const f=LEADER_FORTS.find(f=>f.key===key);if(!f)return null;const p=state.leaderForts[key]??={};if(p.version!==1)Object.assign(p,{version:1,solved:!!state.fates?.[f.leaderId]||!!state.defeatedTrainers?.includes(f.leaderId),stones:FORT_STONE_BOARD.stones.map(p=>[...p]),rings:[...(f.initial||[0,0,0])],moves:0,cache:false});return p;}
export function fortAlreadyCleared(state,f){return !!state.fates?.[f.leaderId]||!!state.defeatedTrainers?.includes(f.leaderId);}
export function fortGuardDefeated(state,f,n){return fortAlreadyCleared(state,f)||!!state.defeatedTrainers?.includes(f.guardIds[n]);}
export function fortGateOpen(state,f,gate){return fortAlreadyCleared(state,f)||(gate===0?fortGuardDefeated(state,f,0):gate===1?leaderFortState(state,f.key).solved:fortGuardDefeated(state,f,1)&&fortGuardDefeated(state,f,2));}
export function fortBoardContains(x,y){const b=FORT_STONE_BOARD;return x>=b.x&&x<b.x+9&&y>=b.y&&y<b.y+9;}
export function fortBoardWall(x,y){return fortBoardContains(x,y)&&FORT_STONE_BOARD.rows[y-FORT_STONE_BOARD.y][x-FORT_STONE_BOARD.x]==='#';}
export function fortStoneAt(state,room,x,y){if(fortForRoom(room)?.kind!=='stones')return -1;return leaderFortState(state,'dorelem').stones.findIndex(s=>s[0]===x&&s[1]===y);}
export function pushFortStone(state,room,x,y,dx,dy){const f=fortForRoom(room);if(f?.kind!=='stones'||!fortGateOpen(state,f,0))return false;const p=leaderFortState(state,f.key),i=fortStoneAt(state,room,x,y),nx=x+dx,ny=y+dy;if(p.solved||i<0||Math.abs(dx)+Math.abs(dy)!==1||!fortBoardContains(nx,ny)||fortBoardWall(nx,ny)||fortStoneAt(state,room,nx,ny)>=0)return false;p.stones[i]=[nx,ny];p.moves++;p.solved=FORT_STONE_BOARD.goals.every(g=>p.stones.some(s=>s[0]===g[0]&&s[1]===g[1]));return true;}
export function turnFortRing(state,key,index){const f=LEADER_FORTS.find(f=>f.key===key);if(!['symbols','scales'].includes(f?.kind)||!Number.isInteger(index)||index<0||index>2||!fortGateOpen(state,f,0))return false;const p=leaderFortState(state,key);if(p.solved)return false;for(const i of (f.kind==='scales'?[index]:[index,(index+1)%3]))p.rings[i]=(p.rings[i]+1)%4;p.moves++;p.solved=p.rings.every((v,i)=>v===f.target[i]);return true;}
export function resetFortPuzzle(state,key){const f=LEADER_FORTS.find(f=>f.key===key);if(!f)return false;const p=leaderFortState(state,key);if(p.solved)return false;p.stones=FORT_STONE_BOARD.stones.map(s=>[...s]);p.rings=[...(f.initial||[0,0,0])];p.moves=0;return true;}
export function leaderFortBlocked(state,room,x,y){const f=fortForRoom(room);if(!f)return false;if(f.kind==='stones'&&(fortBoardWall(x,y)||fortStoneAt(state,room,x,y)>=0))return true;return [12,25,36].some((gx,i)=>x===gx&&y>=16&&y<=18&&!fortGateOpen(state,f,i));}
export function canChallengeFortLeader(state,id,room){const f=fortForLeader(id);if(!f)return true;if(room!==f.room)return false;if(f.leaderId==='LDR-04'&&!cossenneReady(state))return false;if(f.leaderId==='LDR-02'&&!hospiceReady(state))return false;if(f.leaderId==='LDR-03'&&(!warehouseReady(state)||!state.cybressa?.grain))return false;return [0,1,2].every(g=>fortGateOpen(state,f,g));}
export function fortGuardAvailable(state,id){const f=LEADER_FORTS.find(f=>f.guardIds.includes(id));if(!f)return true;const n=f.guardIds.indexOf(id);return n===0||fortGateOpen(state,f,0)&&fortGateOpen(state,f,1);}
export function claimFortCache(state,key){const f=LEADER_FORTS.find(f=>f.key===key);if(!f||!fortGateOpen(state,f,1))return false;const p=leaderFortState(state,key);if(p.cache)return false;p.cache=true;state.poultices=(state.poultices||0)+2;state.smoke=(state.smoke||0)+1;return true;}
export function leaderFortObjective(state,room){const f=fortForRoom(room);if(!f)return null;if(!fortGateOpen(state,f,0))return {spot:f.guardIds[0],text:'Challenge the Dawn Bloom gate knight'};if(!fortGateOpen(state,f,1))return {spot:f.key+'-mechanism',text:f.kind==='stones'?'Push both counterweights onto the flower plates':f.kind==='scales'?'Set the market weights to 1 · 2 · 3':'Match the three rings to the chapter mosaic'};const n=[1,2].find(n=>!fortGuardDefeated(state,f,n));if(n!==undefined)return {spot:f.guardIds[n],text:'Defeat '+f.guards[n]+' to open the inner hall'};if(!fortAlreadyCleared(state,f)&&f.leaderId==='LDR-02'&&!hospiceReady(state))return {spot:'room-exit',text:'Return to the hospice nurses and allocate the medicine'};if(!fortAlreadyCleared(state,f)&&f.leaderId==='LDR-01'&&!state.dorelemClues)return {spot:'room-exit',text:'Ask the stablehand about Pate and Trade before challenging Yusuf'};if(!fortAlreadyCleared(state,f)&&f.leaderId==='LDR-03'&&(!warehouseReady(state)||!state.cybressa?.grain))return {spot:'room-exit',text:'Investigate the warehouses and allocate the grain with the clerk'};if(!fortAlreadyCleared(state,f)&&f.leaderId==='LDR-04'&&!cossenneReady(state))return {spot:'room-exit',text:'Speak to the families and hear the account at Cossenne’s shrine'};return {spot:fortAlreadyCleared(state,f)?'room-exit':f.leaderSpot,text:fortAlreadyCleared(state,f)?'Explore the cleared fort or return to town':'Speak to '+f.leaderName+' in the inner hall'};}
export function leaderFortJournal(state,room){const f=fortForRoom(room);if(!f)return null;return f.name+' · Elite guards '+f.guardIds.filter((_,n)=>fortGuardDefeated(state,f,n)).length+'/3 · '+(leaderFortState(state,f.key).solved?'Mechanism cleared.':'Read the mechanism plaque for a clue. Progress saves; you can return to town to heal.');}
export function installLeaderFortTrainers(expansion,voices){for(const f of LEADER_FORTS)for(let n=0;n<3;n++){const id=f.guardIds[n];if(!expansion.trainers.some(t=>t.id===id))expansion.trainers.push(f.key==='cossenne'?{...COSSENNE_TRAINERS.find(t=>t.id===id)}:{id,name:f.guards[n],role:'Dawn Bloom elite',faction:'Dawn Bloom',runtimeAuthored:true,portraitId:id,ai_tier:'Advanced',team:f.teams[n].map((species,i)=>{const level=f.levels[n]+(i===f.teams[n].length-1?1:0),species_id=legalForm(species,level);if(!DATA.species.some(s=>s.id===species_id))throw Error('Unknown fort guard species');return {slot:i+1,species_id,level,current_form_legal_move_ids:legalMoves(species_id,level)};})});voices[id]={before:n===0?'This is a Dawn Bloom stronghold. Its halls are under our protection. Prove your partners can face an elite guard before you approach the mechanism.':n===1?'You cleared the old mechanism. Now face the inner watch. Our partners have held this fort through worse than a formal challenge.':'The captain stands between you and the leader. You may withdraw and prepare; if you continue, bring your strongest partners.',after:'The watch yields. This passage is yours. Cleared challenges stay cleared; return to town if your partners need rest.',repeat:'You have earned your passage. We will not challenge you again.'};}}
